import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 16
#define TILE_W 16
__global__ void conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ out,
    int N, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW,
    int Hout, int Wout,
    int tiles_h, int tiles_w)
{
    int tile_h = (TILE_H - 1) * strideH + (KH - 1) * dilH + 1;
    int tile_w = (TILE_W - 1) * strideW + (KW - 1) * dilW + 1;
    extern __shared__ float smem[];
    float* s_input = smem;                    // size tile_h * tile_w
    float* s_weight = smem + tile_h * tile_w;  // size KH * KW
    int num_threads = TILE_H * TILE_W;
    int tx = threadIdx.x % TILE_W;
    int ty = threadIdx.x / TILE_W;
    long block_idx = blockIdx.x;
    int tile_w_idx = block_idx % tiles_w;
    long tmp = block_idx / tiles_w;
    int tile_h_idx = tmp % tiles_h;
    tmp /= tiles_h;
    int co = tmp % Cout;
    int n = tmp / Cout;
    int ho = tile_h_idx * TILE_H + ty;
    int wo = tile_w_idx * TILE_W + tx;
    float sum = 0.0f;
    int h_in_start = tile_h_idx * TILE_H * strideH - padH;
    int w_in_start = tile_w_idx * TILE_W * strideW - padW;
    int total_input = tile_h * tile_w;
    int total_w = KH * KW;
    for (int ci = 0; ci < Cin; ci++) {
        const float* x_base = x + ((long)(n * Cin + ci)) * H * W;
        for (int i = threadIdx.x; i < total_input; i += num_threads) {
            int r = i / tile_w;
            int c = i % tile_w;
            int h_in = h_in_start + r;
            int w_in = w_in_start + c;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                val = x_base[h_in * W + w_in];
            }
            s_input[i] = val;
        }
        const float* w_base = w + ((long)(co * Cin + ci)) * KH * KW;
        for (int i = threadIdx.x; i < total_w; i += num_threads) {
            s_weight[i] = w_base[i];
        }
        __syncthreads();
        if (ho < Hout && wo < Wout) {
            int local_h = ty * strideH;
            int local_w = tx * strideW;
            for (int kh = 0; kh < KH; kh++) {
                int ih = local_h + kh * dilH;
                const float* srow = s_input + ih * tile_w;
                const float* wrow = s_weight + kh * KW;
                for (int kw = 0; kw < KW; kw++) {
                    int iw = local_w + kw * dilW;
                    sum += srow[iw] * wrow[kw];
                }
            }
        }
        __syncthreads();
    }
    if (ho < Hout && wo < Wout) {
        long out_idx = ((long)(n * Cout + co) * Hout + ho) * Wout + wo;
        out[out_idx] = sum;
    }
}
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW)
{
    x = x.contiguous();
    weight = weight.contiguous();
    int N = x.size(0);
    int Cin = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int Cout = weight.size(0);
    int KH = weight.size(2);
    int KW = weight.size(3);
    int Hout = (H + 2 * padH - dilH * (KH - 1) - 1) / strideH + 1;
    int Wout = (W + 2 * padW - dilW * (KW - 1) - 1) / strideW + 1;
    auto out = torch::zeros({N, Cout, Hout, Wout}, x.options());
    int tiles_h = (Hout + TILE_H - 1) / TILE_H;
    int tiles_w = (Wout + TILE_W - 1) / TILE_W;
    long total_blocks = (long)N * Cout * tiles_h * tiles_w;
    int threads = TILE_H * TILE_W;
    int tile_h = (TILE_H - 1) * strideH + (KH - 1) * dilH + 1;
    int tile_w = (TILE_W - 1) * strideW + (KW - 1) * dilW + 1;
    size_t shared_bytes = (size_t)(tile_h * tile_w + KH * KW) * sizeof(float);
    conv2d_kernel<<<(unsigned int)total_blocks, threads, shared_bytes>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        N, Cin, H, W,
        Cout, KH, KW,
        strideH, strideW,
        padH, padW,
        dilH, dilW,
        Hout, Wout,
        tiles_h, tiles_w
    );
    return out;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for 2D convolution
    with square input and asymmetric kernel, dilation, and padding.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.use_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1])
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv2d_cuda = conv2d_module.conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda()
        weight = self.weight.cuda()

        out = self.conv2d_cuda(
            x, weight,
            self.stride, self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1, 1)

        return out


